    if ($p -and -not $p.StartsWith('#')) { npm install -g $p }
}

# 4) Azure DevOps CLI extension — install + upgrade ----------------------------
if (Get-Command az -ErrorAction SilentlyContinue) {
    Say "Azure DevOps CLI extension"
    az extension add --name azure-devops --only-show-errors 2>$null
    az extension update --name azure-devops --only-show-errors 2>$null
}

# 5) Claude Code — configure plugins/skills. On WORK use the existing
#    Accenture Enterprise/managed install; only auto-install on personal.
Say "Claude Code plugins & skills"
if (-not (Get-Command claude -ErrorAction SilentlyContinue)) {
    if ($Machine -eq "work") {
        Write-Host "  ! Claude Code not found — install via Accenture's Enterprise/managed channel, then re-run."
    } else {
        npm install -g @anthropic-ai/claude-code
    }
}
Get-Content "$Repo\claude\marketplaces.txt" | ForEach-Object {
    if ($_ -and -not $_.StartsWith('#')) {
        $repo = ($_ -split '=')[1]
        if ($repo) { claude plugin marketplace add $repo.Trim() 2>$null }
    }
}
claude plugin marketplace update 2>$null
Get-Content "$Repo\claude\plugins.txt" | ForEach-Object {
    if ($_ -and -not $_.StartsWith('#')) {
        $p = $_.Trim()
        claude plugin install $p 2>$null
        claude plugin update $p 2>$null
    }
}
$skillsDst = Join-Path $HOME ".claude\skills"
New-Item -ItemType Directory -Force -Path $skillsDst | Out-Null
Copy-Item "$Repo\claude\skills\*" $skillsDst -Recurse -Force
$settingsDst = Join-Path $HOME ".claude\settings.json"
if (-not (Test-Path $settingsDst)) {
    Copy-Item "$Repo\claude\settings.seed.json" $settingsDst
    Write-Host "  Seeded ~/.claude/settings.json"
} else {
    Write-Host "  ~/.claude/settings.json exists — left untouched."
}

# Status line — install script + point settings.json at it (Git Bash + jq at runtime).
$statusDst = Join-Path $HOME ".claude\statusline-command.sh"
Copy-Item "$Repo\claude\statusline-command.sh" $statusDst -Force
if (Test-Path $settingsDst) {
    try {
        $s = Get-Content $settingsDst -Raw | ConvertFrom-Json
        $sl = [pscustomobject]@{ type = "command"; command = "bash ~/.claude/statusline-command.sh" }
        $s | Add-Member -NotePropertyName statusLine -NotePropertyValue $sl -Force
        $s | ConvertTo-Json -Depth 20 | Set-Content $settingsDst
        Write-Host "  Status line configured (needs Git Bash + jq on PATH)."
    } catch { Write-Host "  ! Could not set status line: $_" }
}

# 6) VS Code: extensions + settings --------------------------------------------
Say "VS Code"
if (Get-Command code -ErrorAction SilentlyContinue) {
    Get-Content "$Repo\vscode\extensions.txt" | ForEach-Object {
        if ($_ -and -not $_.StartsWith('#')) { code --install-extension $_.Trim() --force 2>$null }
    }
    $vscodeUser = Join-Path $env:APPDATA "Code\User"
    New-Item -ItemType Directory -Force -Path $vscodeUser | Out-Null
    Copy-Item "$Repo\vscode\settings.json"    (Join-Path $vscodeUser "settings.json")    -Force
    Copy-Item "$Repo\vscode\keybindings.json" (Join-Path $vscodeUser "keybindings.json") -Force
}

# Personal-only extras — skipped on the work profile for compliance
if ($Machine -ne "work") {
    Say "Personal extras (Vercel CLI, Postman)"
    npm install -g vercel
    winget install --id Postman.Postman -e --accept-package-agreements --accept-source-agreements --silent
} else {
    Say "Work profile — skipping personal extras (Vercel CLI, Postman)"
}

Say "Done. Restart your terminal, then run: gh auth login  (and: az login if using Azure)"

